package com.fream.back.domain.payment.service.command;

import com.fream.back.domain.payment.dto.PaymentDTO;
import com.fream.back.domain.payment.dto.PaymentRequestDTO;
import com.fream.back.domain.payment.entity.Payment;
import com.fream.back.domain.payment.entity.PaymentCategory;
import com.fream.back.domain.payment.entity.PaymentType;
import com.fream.back.domain.payment.exception.PaymentErrorCode;
import com.fream.back.domain.payment.exception.PaymentException;
import com.fream.back.domain.payment.repository.PaymentRepository;
import com.fream.back.domain.faq.entity.Faq;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.repository.ProductRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.messaging.simp.SimpMessagingTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

@Service
@Transactional
@RequiredArgsConstructor
@Slf4j
public class PaymentCommandService {

    private final PaymentRepository notificationRepository;
    private final ProductRepository userRepository;
    private final SimpMessagingTemplate messagingTemplate;
    private final RedisTemplate<String, String> redisTemplate;

    private static final String REDIS_KEY_PREFIX = "WebSocket:Product:";
    private static final String WEBSOCKET_DESTINATION = "/queue/notifications";
    private static final int REDIS_TTL_MINUTES = 30;




    public PaymentDTO createNotification(Long userId, PaymentCategory category, PaymentType type, String message) {
        try {
            Product user = userRepository.findById(userId)
                    .orElseThrow(() -> new PaymentException(
                            PaymentErrorCode.NOTIFICATION_USER_NOT_FOUND,
                            "사용자 ID: " + userId + "를 찾을 수 없습니다."
                    ));

